```java
import htsjdk.samtools.*;
import htsjdk.samtools.reference.ReferenceSequenceFileFactory;
import java.nio.file.*;
import java.io.*;

public class Dump {
  public static void main(String[] args) throws Exception {
    Path cram = Paths.get(args[0]);
    Path ref = Paths.get(args[1]);
    SamReaderFactory f = SamReaderFactory.makeDefault()
        .validationStringency(ValidationStringency.SILENT)
        .referenceSequence(ref);
    try (SamReader r = f.open(cram)) {
      PrintStream out = System.out;
      SAMRecordIterator it = r.iterator();
      while (it.hasNext()) {
        SAMRecord rec = it.next();
        if (rec.getReadUnmappedFlag()) continue;
        StringBuilder sb = new StringBuilder();
        sb.append(rec.getReadName()).append('\t');
        sb.append(rec.getFlags()).append('\t');
        sb.append(rec.getContig()).append('\t');
        sb.append(rec.getAlignmentStart()).append('\t');
        sb.append(rec.getMappingQuality()).append('\t');
        sb.append(rec.getCigarString()).append('\t');
        sb.append(rec.getInferredInsertSize()).append('\t');
        sb.append(rec.getReadString()).append('\t');
        byte[] q = rec.getBaseQualities();
        StringBuilder qs = new StringBuilder();
        for (int i=0;i<q.length;i++){ if(i>0) qs.append(','); qs.append((int)q[i]); }
        sb.append(qs);
        out.println(sb);
      }
    }
  }
}
```

