import re, sys
from collections import defaultdict

refseq = None
for line in open('/task/input/reference/ref.fa'):
    if line.startswith('>'):
        refseq = ''
    else:
        refseq += line.strip()

def load(path):
    reads = {}
    for line in open(path):
        f = line.rstrip('\n').split('\t')
        name = f[0]; flags = int(f[1]); start = int(f[3]); mapq = int(f[4])
        cigar = f[5]; tlen = int(f[6]); seq = f[7]
        qual = [int(x) for x in f[8].split(',')] if len(f) > 8 and f[8] else []
        reads.setdefault(name, []).append({
            'flags': flags, 'start': start, 'mapq': mapq, 'cigar': cigar,
            'tlen': tlen, 'seq': seq, 'qual': qual})
    return reads

def walk(read):
    seq = read['seq']
    if read['flags'] & 16:
        seq = seq[::-1].translate(str.maketrans('ACGTNacgtn', 'TGCANtgcan'))
    rp = 0
    gp = read['start']
    for ln, op in re.findall(r'(\d+)([MIDNSHP=X])', read['cigar']):
        ln = int(ln)
        if op in 'M=X':
            for k in range(ln):
                yield gp + k, rp + k, seq[rp + k]
            rp += ln; gp += ln
        elif op == 'I':
            yield gp - 1, rp, ('INS', seq[rp:rp + ln])
            rp += ln
        elif op in 'DN':
            yield gp - 1, rp, ('DEL', ln, seq[rp:rp + 1] if rp < len(seq) else '')
            gp += ln
        elif op == 'S':
            rp += ln

def mismatches(read):
    """(aligned_positions, mismatches) vs reference, MD-style."""
    seq = read['seq']
    if read['flags'] & 16:
        seq = seq[::-1].translate(str.maketrans('ACGTNacgtn', 'TGCANtgcan'))
    rp = 0
    gp = read['start']
    al = 0; mm = 0
    out = []
    for ln, op in re.findall(r'(\d+)([MIDNSHP=X])', read['cigar']):
        ln = int(ln)
        if op in 'M=X':
            for k in range(ln):
                g = gp + k
                rb = refseq[g - 1].upper()
                ob = seq[rp + k].upper()
                al += 1
                if rb != ob:
                    mm += 1
                out.append((g, rp + k, rb, ob))
            rp += ln; gp += ln
        elif op == 'I':
            rp += ln
        elif op in 'DN':
            gp += ln
        elif op == 'S':
            rp += ln
    return al, mm, out

